DROP TABLE IF EXISTS `fact_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_sales` (
  `order_time_fk` bigint NOT NULL,
  `sale_time_fk` bigint NOT NULL,
  `supplier_fk` bigint NOT NULL,
  `customer_fk` bigint NOT NULL,
  `product_fk` bigint NOT NULL,
  `junk_fk` bigint NOT NULL,
  `invoice_nk` bigint DEFAULT NULL,
  `source_system` varchar(10) DEFAULT NULL,
  `fact_sales_amount` decimal(10,2) DEFAULT NULL,
  `fact_num_products` int DEFAULT NULL,
  `fact_cost` decimal(10,2) DEFAULT NULL,
  `shipping_cost` decimal(10,2) DEFAULT NULL,
  `fulfill_time` int DEFAULT NULL,
  `gross_profit` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`order_time_fk`,`sale_time_fk`,`supplier_fk`,`customer_fk`,`product_fk`,`junk_fk`),
  KEY `sale_time_constraint` (`sale_time_fk`),
  KEY `supplier_constraint` (`supplier_fk`),
  KEY `customer_constraint` (`customer_fk`),
  KEY `product_constraint` (`product_fk`),
  KEY `junk_constraint` (`junk_fk`),
  CONSTRAINT `customer_constraint` FOREIGN KEY (`customer_fk`) REFERENCES `dim_customer` (`customer_sk`),
  CONSTRAINT `junk_constraint` FOREIGN KEY (`junk_fk`) REFERENCES `dim_junk` (`junk_sk`),
  CONSTRAINT `order_time_constraint` FOREIGN KEY (`order_time_fk`) REFERENCES `dim_time` (`time_sk`),
  CONSTRAINT `product_constraint` FOREIGN KEY (`product_fk`) REFERENCES `dim_product` (`product_sk`),
  CONSTRAINT `sale_time_constraint` FOREIGN KEY (`sale_time_fk`) REFERENCES `dim_time` (`time_sk`),
  CONSTRAINT `supplier_constraint` FOREIGN KEY (`supplier_fk`) REFERENCES `dim_supplier` (`supplier_sk`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
